     </style>
   </head>
   <body>
     <div id="app"></div>

     <script>
       function fieldComponent({
         id,
         label,
         type,
         name,
         autocomplete,
         placeholder,
         help,
         required = false
       }) {
         return `
           <div class="form-field" id="field-${id}">
             <label for="${id}">${label}${required ? ' <span class="required">*</span>' : ""}</label>
             <input
               id="${id}"
               name="${name}"
               type="${type}"
               ${autocomplete ? `autocomplete="${autocomplete}"` : ""}
               ${placeholder ? `placeholder="${placeholder}"` : ""}
               ${required ? "required" : ""}
               aria-describedby="${id}-help ${id}-error"
             />
             <p class="field-help" id="${id}-help">${help}</p>
             <p class="field-message" id="${id}-error" aria-live="polite"></p>
           </div>
         `;
       }

       function supportFormComponent() {
         return `
           <main class="page">
             <div class="shell">
               <header class="hero">
                 <div class="eyebrow">Support</div>
                 <h1 id="support-form-title">Contact our team</h1>
                 <p>Send us a message and we’ll get back to you as soon as we can.</p>
               </header>

               <section class="card" aria-labelledby="support-form-title">
                 <div class="card-inner">
                   <form id="support-form" novalidate>
                     <div id="form-status" class="status" role="status" aria-live="polite" hidden></div>

                     <div class="form-grid">
                       ${fieldComponent({
                         id: "fullName",
                         name: "fullName",
                         label: "Full name",
                         type: "text",
                         autocomplete: "name",
                         placeholder: "Alex Johnson",
                         help: "Please enter the name you use with your account.",
                         required: true
                       })}
                       ${fieldComponent({
                         id: "email",
                         name: "email",
                         label: "Email address",
                         type: "email",
                         autocomplete: "email",
                         placeholder: "alex@company.com",
                         help: "We'll use this to reply to your request.",
                         required: true
                       })}
                       ${fieldComponent({
                         id: "phone",
                         name: "phone",
                         label: "Phone number",
                         type: "tel",
                         autocomplete: "tel",
                         placeholder: "+1 (555) 123-4567",
                         help: "Optional. Use a format like +1 (555) 123-4567 or 555-123-4567."
                       })}

                       <div class="actions">
                         <button type="submit">Send message</button>
                       </div>
                     </div>
                   </form>
                 </div>
               </section>
             </div>
           </main>
         `;
       }

       function App() {
         return supportFormComponent();
       }

       document.getElementById("app").innerHTML = App();

       const form = document.getElementById("support-form");
       const status = document.getElementById("form-status");

       const fields = {
         fullName: {
           input: document.getElementById("fullName"),
           field: document.getElementById("field-fullName"),
           error: document.getElementById("fullName-error"),
           validate(value) {
             if (!value.trim()) return "Full name is required.";
             return "";
           }
         },
         email: {
           input: document.getElementById("email"),
           field: document.getElementById("field-email"),
           error: document.getElementById("email-error"),
           validate(value) {
             if (!value.trim()) return "Email address is required.";
             if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
               return "Enter a valid email address.";
             }
             return "";
           }
         },
         phone: {
           input: document.getElementById("phone"),
           field: document.getElementById("field-phone"),
           error: document.getElementById("phone-error"),
           validate(value) {
             const trimmed = value.trim();
             if (!trimmed) return "";
             if (!/^[+()\-.\s\d]+$/.test(trimmed) || trimmed.replace(/\D/g, "").length < 7) {
               return "Enter a valid phone number or leave this field blank.";
             }
             return "";
           }
         }
       };

       function setFieldState(name, message) {
         const { field, input, error } = fields[name];
         const invalid = Boolean(message);
         field.classList.toggle("invalid", invalid);
         input.setAttribute("aria-invalid", invalid ? "true" : "false");
         error.textContent = message;
       }

       function validateField(name) {
         const { input, validate } = fields[name];
         const message = validate(input.value);
         setFieldState(name, message);
         return !message;
       }

       function validateForm() {
         const valid = Object.keys(fields).map(validateField).every(Boolean);
         if (valid) {
           status.hidden = false;
           status.textContent = "Thanks — your message is ready to send.";
         } else {
           status.hidden = true;
           status.textContent = "";
         }
         return valid;
       }

       Object.keys(fields).forEach((name) => {
         const { input } = fields[name];
         input.addEventListener("blur", () => validateField(name));
         input.addEventListener("input", () => {
           if (fields[name].error.textContent) validateField(name);
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         if (validateForm()) {
           form.reset();
           Object.keys(fields).forEach((name) => setFieldState(name, ""));
         }
       });
     </script>
   </body>
 </html>

